type TypeKey string

func (tk TypeKey) String() string {
	return string(tk)
}
func (tk TypeKey) URL() string {
	return string(addr.ObjectTypeKeyToIdPrefix + tk)
}
func (tk TypeKey) BundledURL() string {
	return string(addr.BundledObjectTypeURLPrefix + tk)
}

func MarshalTypeKeys(typeKeys []TypeKey) []string {
	res := make([]string, 0, len(typeKeys))
	for _, tk := range typeKeys {
		res = append(res, tk.URL())
	}
	return res
}

func GetTypeKeyFromRawUniqueKey(raw string) (TypeKey, error) {
	uk, err := UnmarshalUniqueKey(raw)
	if err != nil {
		return "", err
	}
	if uk.SmartblockType() != smartblock.SmartBlockTypeObjectType {
		return "", fmt.Errorf("wrong type of unique key %s", uk.SmartblockType().String())
	}
	return TypeKey(uk.InternalKey()), nil
}

func (p *pbc) Convert(sbType model.SmartBlockType) []byte {
	st := p.s.NewState()
	snapshot := &pb.ChangeSnapshot{
		Data: &model.SmartBlockSnapshotBase{
			Blocks:      st.BlocksToSave(),
			Details:     st.CombinedDetails().ToProto(),
			ObjectTypes: domain.MarshalTypeKeys(st.ObjectTypeKeys()),
			Collections: st.Store(),
			Key:         p.s.UniqueKeyInternal(),
			FileInfo:    st.GetFileInfo().ToModel(),
		},
	}
	mo := &pb.SnapshotWithType{
		SbType:   sbType,
		Snapshot: snapshot,
	}
